<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_connection_status( $target_id, $user_id = 0 ) { if ( ! function_exists( 'friends_check_friendship_status' ) ) { return false; } return friends_check_friendship_status( absint( $user_id ?: get_current_user_id() ), absint( $target_id ) ); }
function sd_core_connection_action( $target_id, $action ) { $target_id = absint( $target_id ); $user_id = get_current_user_id(); if ( ! $user_id || ! $target_id || $target_id === $user_id || ! function_exists( 'bp_is_active' ) || ! bp_is_active( 'friends' ) ) { return new WP_Error( 'invalid_connection', __( 'That connection is not available.', 'social-discovery-core' ) ); } $status = sd_core_connection_status( $target_id, $user_id ); if ( 'connect' === $action && 'not_friends' === $status && function_exists( 'friends_add_friend' ) ) { friends_add_friend( $user_id, $target_id ); } elseif ( 'cancel' === $action && 'pending' === $status && function_exists( 'friends_withdraw_friendship' ) ) { friends_withdraw_friendship( $user_id, $target_id ); } elseif ( 'accept' === $action && 'awaiting_response' === $status && function_exists( 'friends_accept_friendship' ) ) { friends_accept_friendship( $target_id, $user_id ); } elseif ( 'reject' === $action && 'awaiting_response' === $status && function_exists( 'friends_reject_friendship' ) ) { friends_reject_friendship( $target_id, $user_id ); } elseif ( 'remove' === $action && 'is_friend' === $status && function_exists( 'friends_remove_friend' ) ) { friends_remove_friend( $user_id, $target_id ); } else { return new WP_Error( 'invalid_state', __( 'That connection state has changed. Refresh and try again.', 'social-discovery-core' ) ); } return sd_core_connection_status( $target_id, $user_id ); }
